画出这段代码的调用过程：

async function register(req) {
  const user = await userService.create(req.body)
  const token = await authService.issueToken(user.id)
  await emailService.sendWelcome(user.email)
  await auditLog.write('register', user.id)
  return { user, token }
}

根据这些表画 ER 图：

CREATE TABLE users(id INT PRIMARY KEY, name VARCHAR(50), email VARCHAR(100));
CREATE TABLE posts(id INT PRIMARY KEY, user_id INT REFERENCES users(id), title VARCHAR(200), body TEXT);
CREATE TABLE comments(id INT PRIMARY KEY, post_id INT REFERENCES posts(id), user_id INT REFERENCES users(id), content TEXT);
